-- Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.payment_submissions(id uuid primary key default gen_random_uuid(),student_name text not null,student_email text not null,payment_reference text not null,payment_date timestamptz not null,note text default '',receipt_path text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.premium_access(id uuid primary key default gen_random_uuid(),student_email text not null,submission_id uuid references public.payment_submissions(id) on delete set null,status text not null default 'approved' check(status in ('approved','expired')),starts_at timestamptz not null default now(),expires_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists public.quiz_results(id uuid primary key default gen_random_uuid(),student_email text,subject text not null,score integer not null,total_questions integer not null,answers jsonb not null default '[]'::jsonb,completed_at timestamptz not null default now());
alter table public.payment_submissions enable row level security; alter table public.premium_access enable row level security; alter table public.quiz_results enable row level security;
drop policy if exists "Public can submit payment" on public.payment_submissions;
create policy "Public can submit payment" on public.payment_submissions for insert to anon,authenticated with check(status='pending' and reviewed_at is null);
revoke all on public.payment_submissions from anon,authenticated; grant insert on public.payment_submissions to anon,authenticated; grant insert(student_name,student_email,payment_reference,payment_date,note,receipt_path,status) on public.payment_submissions to anon,authenticated;
drop policy if exists "Public can insert quiz results" on public.quiz_results; create policy "Public can insert quiz results" on public.quiz_results for insert to anon,authenticated with check(true); grant insert on public.quiz_results to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-receipts','payment-receipts',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp','application/pdf'];
drop policy if exists "Public upload payment receipts" on storage.objects; create policy "Public upload payment receipts" on storage.objects for insert to anon,authenticated with check(bucket_id='payment-receipts');
